import java.util.ArrayList;

public class Main {
    public static void main(String[] args) {
        ArrayList<String> list = new ArrayList<>();
        list.add("Hello");

        // 1. Compile-time Check
        // list.add(123); // Error

        // 2. Runtime Reality (Type Erasure)
        // Inside JVM, it is just ArrayList (raw type)
        String s = list.get(0); 
        // Compiler inserts: (String) list.get(0)

        System.out.println(s);

        // Proof: getClass() is same for all generic types
        ArrayList<Integer> intList = new ArrayList<>();
        boolean sameClass = list.getClass() == intList.getClass();
        System.out.println("Same Class? " + sameClass);
    }
}
